//! Complete immutable-old extraction comparisons. Native source completion is separate.
use crate::{lint::Registry,tracked_policy as policy};
#[path="../fixtures/original_policies/tracked.rs"]mod original;
#[path="../fixtures/native-tracked/fixture.rs"]mod fixture;
fn record(outcome:&crate::run::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
#[test]fn unique_tracked_core_preserves_all_original_sites_lists_construction_scopes_allow_notes_and_reports(){
 for case in fixture::CASES{let root=crate::test_scratch::dir(&format!("tracked-whole-old-{case}"));for(relative,bytes)in fixture::files(case).unwrap(){let path=root.join(relative);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,bytes).unwrap();}
 let options=crate::run::Options{root:root.clone(),lints:vec!["tracked".into(),"tracked_tests".into()],no_cache:true,raw:true,..Default::default()};let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,options.clone()).unwrap();assert!(crate::sem::sem_for(&old.tree).unwrap().errors.is_empty(),"authored whole-old fixture must prepare without parse errors for {case}");let current=crate::run::Engine::new(crate::run::registry(),options).unwrap();for name in["tracked","tracked_tests"]{let expected=old.run_one(old.reg.lints.iter().find(|lint|lint.meta().name==name).unwrap().as_ref());let actual=current.run_one(current.reg.lints.iter().find(|lint|lint.meta().name==name).unwrap().as_ref());assert_eq!(record(&actual),record(&expected),"complete {name} report/ALLOW/order for {case}");if name=="tracked"&&*case!="configured"{assert!(!expected.run.sites.is_empty());}if name=="tracked"&&*case=="procedure_references"{let lines:Vec<_>=expected.run.sites.iter().filter(|site|site.rel=="code/reference_arguments.dm"&&site.line<28).map(|site|site.line).collect();assert_eq!(lines,vec![5,9,16,23],"immutable old parser discards reference arguments, including nested named calls; ordinary/nested global list names stay excluded; direct global/dynamic-constructor arguments are not named positions");}if name=="tracked_tests"&&*case=="maps_tests"{assert!(expected.run.sites.iter().any(|site|site.msg.starts_with("score ")));}if name=="tracked"&&*case=="configured"{assert!(expected.run.sites.is_empty());}println!("TRACKED_WHOLE_ORIGINAL={}",serde_json::json!({"case":case,"name":name,"record":record(&actual)}));let source_text:Vec<_>=expected.run.sites.iter().map(|site|old.tree.site_text(&site.rel,site.line as usize)).collect();println!("ORIGINAL_CONTEXT_TRACKED_OLD={}",serde_json::json!({"case":case,"family":name,"sites":expected.run.sites,"notes":expected.run.notes,"allow_used":expected.allow_used,"source_text":source_text}));}}
}
#[test]fn borrowed_builtin_path_comparison_keeps_exact_original_full_path_meaning(){for child in["","/","/obj","/obj/item/x","/atom/movable/obj/item/x","/mob/living","/turf/x","/area/x","/objekt/x","/datum/a"]{for base in["","/","/obj","/atom","/atom/movable","/mob","/turf","/area","/datum","/obj/item"]{let left=policy::builtin_full_path(child);let right=policy::builtin_full_path(base);let old=left==right||(left.starts_with(&right)&&left.as_bytes().get(right.len())==Some(&b'/'));assert_eq!(policy::is_subtype(child,base),old,"{child} under {base}");}}}
